// ValidateMcpFeedbackResponseBody runs the validations defined on
// McpFeedbackResponseBody
func ValidateMcpFeedbackResponseBody(body *McpFeedbackResponseBody) (err error) {
	if body.ID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("id", "body"))
	}
	if body.McpServerID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("mcp_server_id", "body"))
	}
	if body.Content == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("content", "body"))
	}
	if body.CreatedAt == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("created_at", "body"))
	}
	if body.ID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.id", *body.ID, goa.FormatUUID))
	}
	if body.McpServerID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.mcp_server_id", *body.McpServerID, goa.FormatUUID))
	}
	if body.Severity != nil {
		if !(*body.Severity == "blocked" || *body.Severity == "degraded" || *body.Severity == "cosmetic") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.severity", *body.Severity, []any{"blocked", "degraded", "cosmetic"}))
		}
	}
	if body.CreatedAt != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.created_at", *body.CreatedAt, goa.FormatDateTime))
	}
	return
}
